// Avalanche gas for the mint. The payload bytes are the unwrap that an executed
// Osmosis GMP used: WAVAX.withdraw, then native AVAX to the recipient. The two
// recipient slots start empty. Axelar relays this leg. This page does not.

import { WAVAX_ON_OSMOSIS } from "./route.js";

export const OSMOSIS_TO_AXELAR = "channel-208";
export const AXELAR_GMP_ACCOUNT = "axelar1dv4u5k73pzqrxlzujxg3qp8kvc3pje7jtdvu72npnt5zhq05ejcsn5qme5";
export const AXELAR_GAS_RECEIVER = "axelar1aythygn6z5thymj6tmzfwekzh05ewg3l7d6y89";
export const AXELAR_AVALANCHE_UNWRAP = "0xce16F69375520ab01377ce7B88f5BA8C48F8D666";
export const AXELAR_ESTIMATE = "https://api.axelarscan.io/gmp/estimateGasFee";
// Destination execution budget passed to the Axelar fee quote.
export const AXELAR_DEST_GAS = "1000000";
const RECIPIENT_AT = [44, 844];
const TEMPLATE = hexToBytes("");

function hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let index = 0; index < out.length; index += 1) {
    out[index] = Number.parseInt(hex.slice(index * 2, index * 2 + 2), 16);
  }
  return out;
}

function recipientBytes(address) {
  const hex = String(address || "").replace(/^0x/i, "").toLowerCase();
  if (!/^[\da-f]{40}$/.test(hex)) throw new Error("The Avalanche recipient is not an address.");
  return hexToBytes(hex);
}

export function axelarNativePayload(recipient) {
  const next = new Uint8Array(TEMPLATE);
  const raw = recipientBytes(recipient);
  for (const at of RECIPIENT_AT) next.set(raw, at);
  return next;
}

export function axelarNativeMemo(recipient, feeAmount) {
  const fee = BigInt(feeAmount);
  if (fee <= 0n) throw new Error("Axelar did not price the Avalanche relay.");
  return JSON.stringify({
    destination_chain: "avalanche",
    destination_address: AXELAR_AVALANCHE_UNWRAP,
    type: 2,
    fee: { amount: fee.toString(), recipient: AXELAR_GAS_RECEIVER },
    payload: [...axelarNativePayload(recipient)],
  });
}

export function avaxBudget(gasPrice, relayGas, axelarFee) {
  const price = BigInt(gasPrice);
  const gas = BigInt(relayGas);
  const fee = BigInt(axelarFee);
  if (price <= 0n || gas <= 0n || fee <= 0n) throw new Error("Avalanche gas price was not read.");
  return price * gas + fee;
}

export function estimateUrl() {
  const url = new URL(AXELAR_ESTIMATE);
  url.searchParams.set("sourceChain", "osmosis");
  url.searchParams.set("destinationChain", "Avalanche");
  url.searchParams.set("sourceTokenSymbol", "axlAVAX");
  url.searchParams.set("gasLimit", AXELAR_DEST_GAS);
  return url;
}

export { WAVAX_ON_OSMOSIS };
